            if '"user"' not in line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            m = d.get("message") or {}
            if m.get("role") != "user" or m.get("toolName"):
                continue
            text = extract_text(m.get("content")).strip()
            if not text or is_noise(text):
                continue
            yield {
                "t": taiwan_time(d.get("timestamp")),
                "src": AGENT_NAMES.get(agent, agent),
                "who": "真人訊息",
                "text": re.sub(r"\s+", " ", text)[:1000],
            }
