    for vf in glob.glob(VERBATIM_DIR + "/*.jsonl"):
        for line in open(vf, encoding="utf-8", errors="ignore"):
            try:
                e = json.loads(line)
                e["ref"] = vf
                entries.append(e)
            except Exception:
                pass
    # 來源一之二：對話原文檔還活著、但尚未收割的訊息
    for e in scan_sessions():
        e = dict(e, ref="sessions", text=e["text"][:300])
        entries.append(e)
