            f = open(path, encoding="utf-8", errors="ignore")
        except OSError:
            continue
        for i, line in enumerate(f, 1):
            if "👤 教練：" not in line:
                continue
            text = line.split("👤 教練：", 1)[1].strip()
            if not text or is_noise(text):
                continue
            entries.append({
                "t": day,
                "src": "每日摘要",
                "who": "教練",
                "text": re.sub(r"\s+", " ", text)[:300],
                "ref": "%s:%d" % (path, i),
            })
        f.close()
    # 去重（作夢任務會大量複製同句話）
    seen, uniq = set(), []
    for e in sorted(entries, key=lambda x: x["t"]):
        key = e["text"][:120]
        if key in seen:
            continue
        seen.add(key)
        uniq.append(e)
    os.makedirs(os.path.dirname(INDEX), exist_ok=True)
    with open(INDEX, "w", encoding="utf-8") as f:
        for e in uniq:
            f.write(json.dumps(e, ensure_ascii=False) + "\n")
    print("✅ 索引重建完成：%d 句真人的話 → %s" % (len(uniq), INDEX))


def expand_keywords(words):
    """同義詞展開：查任一詞，同組的詞一起查（模糊搜尋第一階段）"""
    out = set(words)
    try:
        groups = json.load(open(SYNONYMS, encoding="utf-8"))
        for g in groups:
            if any(w in g for w in words):
                out.update(g)
    except Exception:
        pass
    return list(out)


def search(words, limit=10):
    if not os.path.exists(INDEX):
        print("索引不存在，先建一次……")
        build()
    kws = expand_keywords(words)
    hits = []
    for line in open(INDEX, encoding="utf-8"):
        if not any(k in line for k in kws):
            continue
        try:
            e = json.loads(line)
        except Exception:
            continue
        if any(k in e["text"] for k in kws):
            hits.append(e)
    hits.sort(key=lambda x: x["t"], reverse=True)
    shown = hits[:limit]
    label = " / ".join(kws)
    print("🔎 查「%s」：共 %d 筆，顯示最近 %d 筆（台灣時間）\n" % (label, len(hits), len(shown)))
    for e in shown:
        print("[%s]（%s·%s）%s" % (e["t"], e["src"], e["who"], e["text"][:150]))
    if len(hits) > limit:
        print("\n……還有 %d 筆，要看更多：recall.py --limit %d %s" % (len(hits) - limit, limit + 10, " ".join(words)))


if __name__ == "__main__":
    args = sys.argv[1:]
    if not args or args == ["--help"]:
        print(__doc__)
        sys.exit(0)
    did = False
    if "--harvest" in args:
        harvest()
        did = True
    if "--build" in args:
        build()
        did = True
    if did:
        sys.exit(0)
    limit = 10
    if "--limit" in args:
        i = args.index("--limit")
        limit = int(args[i + 1])
        del args[i:i + 2]
    search(args, limit)

